import datetime,hashlib,json,os,pathlib,subprocess,sys,time
D=pathlib.Path(__file__).resolve().parent;label,script=sys.argv[1:3];assert pathlib.Path(script).name==script
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
cmd=[sys.executable,'-B','-X','utf8',str(D/script),*sys.argv[3:]];rec={'command':cmd,'started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_sha256':sha(D/script),'hidden':True,'below_normal':True,'timeout_seconds':50};(D/(label+'-source.py')).write_bytes((D/script).read_bytes());(D/(label+'-started.json')).write_text(json.dumps(rec,indent=2),encoding='utf-8');start=time.monotonic()
p=subprocess.run(cmd,capture_output=True,timeout=50,creationflags=subprocess.CREATE_NO_WINDOW|subprocess.BELOW_NORMAL_PRIORITY_CLASS,env={**os.environ,'PYTHONDONTWRITEBYTECODE':'1','PYTHONIOENCODING':'utf-8'});(D/(label+'-stdout.txt')).write_bytes(p.stdout);(D/(label+'-stderr.txt')).write_bytes(p.stderr);rec.update(exit_code=p.returncode,elapsed_seconds=time.monotonic()-start,finished_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),stdout_sha256=sha(D/(label+'-stdout.txt')),stderr_sha256=sha(D/(label+'-stderr.txt')));(D/(label+'-execution.json')).write_text(json.dumps(rec,indent=2),encoding='utf-8');print(p.stdout.decode());print(p.stderr.decode());print(json.dumps(rec));sys.exit(p.returncode)
